export interface MfeInitFunctionConfig {

  // An html element to render an MFE into.
  element: HTMLElement;

  // A string token representing the current locale.
  // NOTE: Neon and mfe-utils have their own locale setup
  // and do not use this locale string.
  locale: string;

  // Optional information about servers.
  // Note that your MFE should have default servers it hits
  // in case this information is not available.
  serverConfig?: Record<string, string>;

  //When you bootstrap using another instance of React,
  //There is a disconnect between routers. The child mfe needs to
  //use a MemoryRouter to get around this and listen for 'route-change'
  //events fired by the ApplicationShell.  This variable can let
  //the mfe know how much of the url to truncate before calling navigate().
  //Example: 'mfe-1/*' is where this mfe is injected, so when listening
  //for a route change to mfe-1/page-1, the callback can modify the string to
  //be navigate([page-1]);
  injectionRoute?: string;

  // Any other information could be passed into the mfe configuration.
  //
  // This information cannot change throughout the lifecycle of your MFE.
  // If you need to work with data that will change, then do not pass it in here.
  // Instead use the event framework.
  // See addMfeEventListener() and dispatchMfeEvent().
  //
  // This information must be able to be serialized and deserialized with
  // JSON.parse(JSON.stringify(yourValue)). Do not include functions or
  // circular pointers.
  //
  // TODO: If you notice that several MFEs are all using the same property, please
  // contact the Voltron team through the #neon slack channel and let them know you would
  // like a new optional variable added to this file.
  [key: string]: any

}